package com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.verify;
import com.bct.ngtpa.apiservice.application.dto.auth.otp.*;import com.bct.ngtpa.apiservice.application.dto.session.authflow.*;import com.bct.ngtpa.apiservice.application.port.in.VerifyLoginOtpUseCase;import com.bct.ngtpa.apiservice.application.port.out.*;import com.bct.ngtpa.apiservice.application.usecase.auth.login.otp.*;import java.time.*;import java.util.Objects;import reactor.core.publisher.Mono;
public final class LoginOtpVerifyService implements VerifyLoginOtpUseCase {private final LoginProtectedAuthFlowContextLoader loader;private final OtpChallengePort otp;private final LoginOtpVerifiedSessionPort verifiedSession;private final AuthFlowSessionCancellationPort cancellation;private final Clock clock;public LoginOtpVerifyService(LoginProtectedAuthFlowContextLoader l,OtpChallengePort o,LoginOtpVerifiedSessionPort v,AuthFlowSessionCancellationPort c,Clock k){loader=Objects.requireNonNull(l);otp=Objects.requireNonNull(o);verifiedSession=Objects.requireNonNull(v);cancellation=Objects.requireNonNull(c);clock=Objects.requireNonNull(k);}public Mono<VerifyLoginOtpResult> verify(VerifyLoginOtpCommand c){return loader.load(new LoginProtectedAuthFlowContextCommand(c.authFlowSessionId(),c.csrfToken(),c.origin(),c.referer(),c.correlationId(),AuthFlowStatus.OTP_SENT,true)).flatMap(x->x.isValid()?verifyActive(c,x):Mono.just(result(VerifyLoginOtpStatus.AUTH_FLOW_INVALID,null,false))).onErrorReturn(result(VerifyLoginOtpStatus.SYSTEM_FAILED,null,false));}private Mono<VerifyLoginOtpResult> verifyActive(VerifyLoginOtpCommand c,LoginProtectedAuthFlowContextResult x){return otp.verifyChallenge(new VerifyOtpChallengeCommand(x.activeOtpChallengeId(),c.otpCode(),clock.instant())).flatMap(r->switch(r.outcome()){case VALID->verifiedSession.markVerified(c.authFlowSessionId(),c.correlationId()).thenReturn(result(VerifyLoginOtpStatus.VERIFIED_READY,null,false));case INVALID->Mono.just(result(VerifyLoginOtpStatus.INVALID,r.remainingAttempts(),false));case EXPIRED->Mono.just(result(VerifyLoginOtpStatus.EXPIRED,null,false));case LOCKED->cancellation.cancel(new AuthFlowSessionId(c.authFlowSessionId()),AuthFlowSessionCancellationReason.SECURITY_REJECTION,clock.instant()).thenReturn(result(VerifyLoginOtpStatus.VERIFY_ATTEMPTS_EXCEEDED,0,true));case ALREADY_VERIFIED->Mono.just(result(VerifyLoginOtpStatus.ALREADY_VERIFIED,null,false));default->Mono.just(result(VerifyLoginOtpStatus.AUTH_FLOW_INVALID,null,false));});}private VerifyLoginOtpResult result(VerifyLoginOtpStatus s,Integer remaining,boolean clear){return new VerifyLoginOtpResult(s,remaining,clear);}}
